1	// Acceptance test for the change request:
2	//   "Show money properly everywhere. Use a dollar sign and cents, like $100.00."
3	//
4	// Every value the app surfaces as MONEY must be shown "properly": a leading dollar sign and the
5	// amount written to two decimal places of cents, exactly as the request illustrates with $100.00.
6	// The app surfaces money in three places, each behind a stable anchor:
7	//   - invoice-amount              — an invoice's amount, on a project's detail page
8	//   - project-invoices-total      — what a project's invoices add up to
9	//   - dashboard-outstanding-total — how much money is still owed, on the dashboard
10	// A bare number (100.00) or one missing its cents (100) is NOT "money shown properly", so each
11	// assertion below requires the dollar sign AND the two cents digits.
12	//
13	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed (the app's /__test__
14	// endpoint): `clients` honours { id, name, email }, `projects` honours { id, name, clientId } and
15	// `invoices` honours { id, amount, projectId, status }.
16	import { test, expect, type Page, type Locator } from '@playwright/test';
17	import { resetAndSeed } from '../support/seed';
18	
19	// "Money shown properly": a dollar sign, the whole-dollar amount, a decimal point and exactly two
20	// cents digits — e.g. $100.00. Thousands grouping ($1,200.00) is allowed but not required, so the
21	// matcher does not pin one grouping style; what it does require — and what this change is about — is
22	// the leading "$" and the trailing ".00". The amounts seeded below all stay under a thousand, so
23	// grouping never actually arises. The match is anchored (^…$) so the cell carries the money value
24	// and nothing else.
25	const money = (dollars: number): RegExp => {
26	  const whole = Math.trunc(dollars).toLocaleString('en-US').replace(/,/g, ',?');
27	  return new RegExp(`^\\$${whole}\\.00$`);
28	};
29	
30	const amountOf = (page: Page, id: number): Locator =>
31	  page.getByTestId(`invoice-row-${id}`).getByTestId('invoice-amount');
32	
33	// Reach the dashboard the way a user would — follow its nav link from the home screen — rather than
34	// pinning the dashboard's URL.
35	async function openDashboard(page: Page): Promise<void> {
36	  await page.goto('/');
37	  const nav = page.getByTestId('nav-dashboard');
38	  await expect(nav).toBeVisible();
39	  await nav.click();
40	  await expect(page.getByTestId('dashboard-page')).toBeVisible();
41	  await expect(page.getByTestId('dashboard')).toBeVisible();
42	}
43	
44	test.describe('Money is shown properly — dollar sign and cents', () => {
45	  test('each invoice amount on a project is shown as $amount.cc', async ({ page }) => {
46	    await resetAndSeed({
47	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
48	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
49	      invoices: [
50	        { id: 1, amount: 100, projectId: 1, status: 'UNPAID' },
51	        { id: 2, amount: 250, projectId: 1, status: 'UNPAID' },
52	        // A paid invoice still carries an amount, and it too must be shown properly.
53	        { id: 3, amount: 50, projectId: 1, status: 'PAID' },
54	      ],
55	    });
56	
57	    await page.goto('/projects/1');
58	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
59	
60	    await expect(amountOf(page, 1)).toHaveText(money(100));
61	    await expect(amountOf(page, 2)).toHaveText(money(250));
62	    await expect(amountOf(page, 3)).toHaveText(money(50));
63	  });
64	
65	  test("a project's invoices total is shown as $amount.cc", async ({ page }) => {
66	    await resetAndSeed({
67	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
68	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
69	      invoices: [
70	        { id: 1, amount: 100, projectId: 1, status: 'UNPAID' },
71	        { id: 2, amount: 250, projectId: 1, status: 'UNPAID' },
72	        { id: 3, amount: 50, projectId: 1, status: 'UNPAID' },
73	      ],
74	    });
75	
76	    await page.goto('/projects/1');
77	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
78	
79	    // 100 + 250 + 50 = 400, shown properly.
80	    await expect(page.getByTestId('project-invoices-total')).toHaveText(money(400));
81	  });
82	
83	  test('a project with no invoices still shows its total as money: $0.00', async ({ page }) => {
84	    await resetAndSeed({
85	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
86	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
87	      invoices: [],
88	    });
89	
90	    await page.goto('/projects/1');
91	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
92	
93	    // Nothing invoiced, but zero is money too — it is shown as $0.00, not a bare 0.
94	    await expect(page.getByTestId('project-invoices-total')).toHaveText(money(0));
95	  });
96	
97	  test('the dashboard outstanding total is shown as $amount.cc', async ({ page }) => {
98	    // Two SENT invoices (120 + 230 = 350 still owed) and one paid (400, no longer owed). Money owed
99	    // counts only invoices that have actually been sent, so the sent pair is what is owed.
100	    await resetAndSeed({
101	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
102	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
